WITH k(bid,key) AS (VALUES ('boe26-4695aab79b5d07133858cf8c',$k$النظام العام للبيئة$k$),('boe26-6d5b7a978cf01e426897c877',$k$الفحص الفني الدوري$k$),('boe26-b7b6f1348954f58aa8610090',$k$الهيئة العامة للرياضة$k$),('boe26-7611a95fe8dd6dacf15de4d5',$k$الهيئة العامة للمساحة$k$),('boe26-3a463848333bb6b410fabbc9',$k$اللجان الإشرافية$k$),('boe26-65e05bd8c1b2843f92fb7994',$k$المخالفات البلدية$k$),('boe26-991c74f73b3dcfe1021cccb9',$k$المهددة بالانقراض$k$),('boe26-c04c6c0b7d8bd375a341e3e5',$k$الرهن التجاري$k$),('boe26-a7bc10626440105f10c6d08e',$k$الضمان الاجتماعي$k$),('boe26-9000690f4bddbd2b25f1d09d',$k$نظام الكهرباء$k$),('boe26-950044f910153026b5bf31af',$k$المراعي والغابات$k$),('boe26-e5c06cbaab583747a8da31e4',$k$المناطق المحمية$k$),('boe26-eb3938d9ba353c9db147e801',$k$نظام المنافسة$k$),('boe26-fc1e16c803147e8894c4d089',$k$المستحضرات الصيدلانية$k$),('boe26-7a8cdf9c2ebb7e42a9419051',$k$لحماية الحياة الفطرية$k$),('boe26-7d0e1ff55f6b1ea632c1ed75',$k$تصنيف المقاولين$k$),('boe26-e6016f7730dd244be8c6025e',$k$صندوق الاستثمارات العامة$k$),('boe26-689d84402e6d3a5cfaca82a5',$k$صيد الحيوانات$k$),('boe26-62c91ee890ea1e76346332e9',$k$مؤسسة النقد$k$),('boe26-492c090bd360a722a341962a',$k$مكافحة التستر$k$))
SELECT json_agg(json_build_object(
 'boe_id',k.bid,'key',k.key,'old',(SELECT json_build_object('name',l.name,'guid',l.guid,'url',l.url,'issued',l.issued_hijri,'published',l.published_hijri,'published_g',l.published_gregorian::text,'status',l.status_at_source,'instruments',l.instruments,'units',l.article_count,
   'match',(SELECT json_build_object('hakeem',m.hakeem_system_id,'method',m.method,'by',m.decided_by) FROM boe.current_match m WHERE m.guid=l.guid),
   'first',(SELECT json_agg(json_build_object('seq',u.seq,'h',u.heading,'b',left(u.body,400)) ORDER BY u.seq) FROM boe.unit u WHERE u.law_id=l.id AND u.seq<=2),
   'last',(SELECT json_agg(json_build_object('seq',u.seq,'h',u.heading,'b',left(u.body,500)) ORDER BY u.seq) FROM (SELECT * FROM boe.unit u2 WHERE u2.law_id=l.id ORDER BY u2.seq DESC LIMIT 2) u)) FROM boe.law l WHERE l.id=k.bid),
 'hakeem_candidates',(SELECT json_agg(c) FROM (SELECT s.id, s.name, s."articleCount" n, s.preamble_royal_decree instr, s.preamble_effective_from::date::text eff, s.instrument_kind kind,
   (SELECT verified_status FROM verification v WHERE v.object_type='work' AND v.object_id=s.id ORDER BY v.verified_at DESC, v.id DESC LIMIT 1) status,
   (SELECT json_agg(json_build_object('work',sm.work_key,'role',sm.role)) FROM search_surface_member sm WHERE sm.system_id=s.id) work,
   similarity(s.name,(SELECT name FROM boe.law WHERE id=k.bid)) sim
   FROM legal_systems s WHERE s.name LIKE '%'||k.key||'%' OR similarity(s.name,(SELECT name FROM boe.law WHERE id=k.bid))>0.45 ORDER BY sim DESC LIMIT 4) c),
 'hakeem_repeal_clauses',(SELECT json_agg(r) FROM (SELECT a."lawName" law, a."legalSystemId" sid, a."articleNumber" art, left(a.content,600) text FROM legal_articles a WHERE a."articleBis"<100 AND a.content LIKE '%'||k.key||'%' AND (a.content ~ '(يلغ|يُلغ|تلغ|تُلغ|يحل |يحلّ|إلغاء)') ORDER BY length(a.content) LIMIT 5) r),
 'boe_repeal_clauses',(SELECT json_agg(r) FROM (SELECT l2.name law, l2.status_at_source st, l2.issued_hijri iss, l2.published_hijri pub, u.seq, left(u.body,600) text FROM boe.unit u JOIN boe.law l2 ON l2.id=u.law_id WHERE u.law_id<>k.bid AND u.body LIKE '%'||k.key||'%' AND (u.body ~ '(يلغ|يُلغ|تلغ|تُلغ|يحل |يحلّ|إلغاء)') ORDER BY l2.status_at_source='ساري' DESC, length(u.body) LIMIT 5) r)
)) FROM k